import { Platform } from 'react-native'
import {
  Passkey,
  type PasskeyCreateRequest,
  type PasskeyCreateResult,
  type PasskeyGetRequest,
  type PasskeyGetResult,
} from 'react-native-passkey'
import { apiRequest } from './api'

export type Log = (message: string) => void

// Options returned by the API are generated by @simplewebauthn/server and go
// straight to the phone, so the library types are only used at the boundary.
type PasskeyOptionsWithCredentials = { allowCredentials?: unknown[] }

// The API requires "type" and "clientExtensionResults", which the phone may omit.
function withRequiredFields<T extends { id: string; rawId?: string }>(
  result: T,
) {
  return {
    ...result,
    rawId: result.rawId ?? result.id,
    type: 'public-key' as const,
    clientExtensionResults:
      (result as { clientExtensionResults?: object }).clientExtensionResults ??
      {},
  }
}

// Name shown in "My passkeys" (the API accepts up to 60 characters).
function deviceName(): string {
  const constants = Platform.constants as { Brand?: string; Model?: string }
  const name = [constants.Brand, constants.Model].filter(Boolean).join(' ')
  return (name || 'Android device').slice(0, 60)
}

// Creates a passkey on this phone for the signed-in student:
// POST /auth/passkeys -> Credential Manager -> POST /auth/passkey/register.
export async function createPasskey(idToken: string, log: Log) {
  log('POST /auth/passkeys (asking for registration options)')
  const options = await apiRequest<PasskeyCreateRequest>('/auth/passkeys', {
    method: 'POST',
    token: idToken,
  })
  log(`options received (rp.id=${options.rp.id})`)

  log('opening the system sheet to create the passkey...')
  const created: PasskeyCreateResult = await Passkey.create(options)
  log(`passkey created on the phone (id=${created.id.slice(0, 12)}...)`)

  log('POST /auth/passkey/register')
  const registered = await apiRequest<unknown>('/auth/passkey/register', {
    method: 'POST',
    body: { response: withRequiredFields(created), deviceName: deviceName() },
  })
  log(`registered: ${JSON.stringify(registered)}`)
}

// Gets a custom token with a passkey:
// POST /auth/passkey/login/options -> Credential Manager -> POST /auth/passkey/login/verify.
export async function getCustomTokenWithPasskey(
  matricula: string,
  log: Log,
): Promise<string> {
  log('POST /auth/passkey/login/options')
  const options = await apiRequest<
    PasskeyGetRequest & PasskeyOptionsWithCredentials
  >('/auth/passkey/login/options', { method: 'POST', body: { matricula } })

  // The API answers the same way for unknown, non-student and passkey-less
  // matriculas, with an empty list and no challenge stored.
  if (!options.allowCredentials?.length) {
    throw new Error('No passkey found for this matricula.')
  }
  log(`options received (${options.allowCredentials.length} passkey(s))`)

  log('opening the system sheet to sign in...')
  const assertion: PasskeyGetResult = await Passkey.get(options)
  log(`assertion signed on the phone (id=${assertion.id.slice(0, 12)}...)`)

  log('POST /auth/passkey/login/verify')
  const { customToken } = await apiRequest<{ customToken: string }>(
    '/auth/passkey/login/verify',
    { method: 'POST', body: { response: withRequiredFields(assertion) } },
  )
  log(`custom token received (${customToken.length} chars)`)
  return customToken
}
